<template>
  <v-container grid-list-xs fluid>
    <!-- Loading Overlay -->
    <v-overlay :value="overlay" z-index="1000">
      <v-progress-circular
        color="primary"
        indeterminate
        size="50"
      ></v-progress-circular>
    </v-overlay>

    <!-- Notification Snackbar -->
    <v-snackbar v-model="snackbar" :color="snackbarColor" :timeout="5000" top>
      {{ snackbarMessage }}
      <template v-slot:action="{ attrs }">
        <v-btn text v-bind="attrs" v-on="(snackbar = false)">Close</v-btn>
      </template>
    </v-snackbar>

    <!-- Confirmation Dialog -->
    <v-dialog v-model="confirmDialog" max-width="600">
      <v-card>
        <v-toolbar class="error darken-2 text-h6 font-weight-bold" dark>
          <v-icon color="white" left large>mdi-alert-circle</v-icon>
          Confirm Leave Cancellation
        </v-toolbar>
        <v-card-text class="pt-4">
          <v-alert type="warning" dense outlined class="mb-4">
            <div class="font-weight-bold mb-2">
              ⚠️ This action cannot be undone
            </div>
            <div class="caption">
              You are about to cancel your approved unpaid leave. Please review
              the details carefully before confirming.
            </div>
          </v-alert>

          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mt-3 mb-1"
          >
            LEAVE TYPE
          </div>
          <div class="text-body-1 font-weight-medium">
            {{ requestData.leaveCategory }}
          </div>

          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mt-3 mb-1"
          >
            ORIGINAL LEAVE PERIOD
          </div>
          <div class="text-body-1 font-weight-medium">
            {{ formatDate(requestData.startDate) }} -
            {{ formatDate(requestData.endDate) }}
            <span class="grey--text">({{ requestData.days }} days)</span>
          </div>

          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mt-3 mb-1"
          >
            CANCELLATION DATE
          </div>
          <div class="text-body-1 font-weight-medium">
            {{ formatDate(cancellationDate) }}
          </div>

          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mt-3 mb-1"
          >
            DAYS TO BE CANCELLED
          </div>
          <div class="text-body-1 font-weight-medium">
            {{ daysToBeCancelled }} days
          </div>

          <div
            class="text-caption font-weight-bold grey--text text--darken-2 mt-3 mb-1"
          >
            CANCELLATION REASON
          </div>
          <div
            class="text-body-1 font-weight-medium"
            style="white-space: pre-wrap;"
          >
            {{ cancellationReason }}
          </div>
        </v-card-text>
        <v-card-actions>
          <v-spacer></v-spacer>
          <v-btn text @click="confirmDialog = false">
            <v-icon left>mdi-close</v-icon>
            No, Keep Leave
          </v-btn>
          <v-btn
            color="error"
            text
            @click="submitCancellation"
            :loading="submitting"
          >
            <v-icon left>mdi-check</v-icon>
            Yes, Cancel Leave
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    <!-- Header Section -->
    <v-row>
      <v-col cols="12">
        <v-card class="mx-auto" flat>
          <v-card-title class="error darken-1 white--text" dark>
            <v-icon left color="white" size="28">mdi-calendar-remove</v-icon>
            Cancel Unpaid Leave
            <v-spacer></v-spacer>
            <v-chip
              color="white"
              text-color="error"
              class="ml-2 font-weight-bold"
            >
              Cancellation Request
            </v-chip>
          </v-card-title>
          <v-card-text class="pa-6">
            <v-row align="center">
              <v-col cols="auto">
                <v-avatar color="error" size="56" class="elevation-2">
                  <v-icon color="white" size="28">mdi-cancel</v-icon>
                </v-avatar>
              </v-col>
              <v-col>
                <h3 class="text-h5 font-weight-bold mb-2">
                  Make Leave Cancellation
                </h3>
                <p class="text-body-1 font-weight-medium mb-0">
                  Cancel your approved unpaid leave by providing a cancellation
                  date and reason.
                </p>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>
      </v-col>
    </v-row>

    <!-- Main Content -->
    <v-row class="mt-4">
      <!-- Left Column: Leave Details -->
      <v-col cols="12" lg="7">
        <leave-details-display
          :requestId="requestId"
          @requestData="populateRequestData"
          ref="leaveDetailsDisplay"
        />

        <!-- Cancellation Impact Card -->
        <v-card outlined class="elevation-3 mt-4" v-if="cancellationDate">
          <v-card-title class="orange darken-1 white--text py-3">
            <v-icon left color="white">mdi-alert</v-icon>
            Cancellation Impact
          </v-card-title>
          <v-card-text class="pa-4">
            <v-alert type="info" dense outlined class="mb-3">
              <div class="caption">
                <strong>Note:</strong> Cancelling from
                {{ formatDate(cancellationDate) }} will terminate your leave
                early and restore unused days.
              </div>
            </v-alert>

            <v-row dense>
              <v-col cols="6">
                <v-card outlined class="pa-3 text-center green lighten-5">
                  <div class="caption grey--text text--darken-2 mb-1">
                    Days Utilized
                  </div>
                  <div
                    class="text-h5 font-weight-bold green--text text--darken-2"
                  >
                    {{ daysUtilized }}
                  </div>
                </v-card>
              </v-col>
              <v-col cols="6">
                <v-card outlined class="pa-3 text-center red lighten-5">
                  <div class="caption grey--text text--darken-2 mb-1">
                    Days to Cancel
                  </div>
                  <div
                    class="text-h5 font-weight-bold red--text text--darken-2"
                  >
                    {{ daysToBeCancelled }}
                  </div>
                </v-card>
              </v-col>
            </v-row>

            <!-- Timeline Visual -->
            <div class="mt-4">
              <div class="caption grey--text text--darken-2 mb-2">
                Leave Timeline
              </div>
              <v-timeline dense>
                <v-timeline-item color="blue" small>
                  <div class="caption">
                    <strong>Started:</strong>
                    {{ formatDate(requestData.startDate) }}
                  </div>
                </v-timeline-item>
                <v-timeline-item color="orange" small>
                  <div class="caption">
                    <strong>Cancelling:</strong>
                    {{ formatDate(cancellationDate) }}
                  </div>
                </v-timeline-item>
                <v-timeline-item color="grey" small>
                  <div class="caption">
                    <strong>Originally Ending:</strong>
                    {{ formatDate(requestData.endDate) }}
                  </div>
                </v-timeline-item>
              </v-timeline>
            </div>
          </v-card-text>
        </v-card>
      </v-col>

      <!-- Right Column: Cancellation Form -->
      <v-col cols="12" lg="5">
        <v-card outlined class="elevation-3">
          <v-card-title class="error darken-1 white--text py-3">
            <v-icon left color="white">mdi-form-select</v-icon>
            Cancellation Details
          </v-card-title>

          <v-card-text class="pa-4">
            <!-- Important Notice -->
            <v-alert type="warning" dense outlined border="left" class="mb-4">
              <div class="font-weight-bold mb-1">
                <v-icon small color="warning">mdi-alert</v-icon>
                Important Information
              </div>
              <ul class="caption pl-4">
                <li>
                  Cancellation date must be between leave start and end dates
                </li>
                <li>You can backdate the cancellation if needed</li>
                <li>Remaining days after cancellation date will be restored</li>
                <li>This action requires supervisor approval</li>
              </ul>
            </v-alert>

            <v-form ref="form" v-model="valid">
              <!-- Cancellation Date -->
              <div class="mb-4">
                <div class="text-subtitle-1 font-weight-bold mb-2">
                  Cancellation Date *
                </div>
                <v-menu
                  v-model="cancellationDateMenu"
                  :close-on-content-click="false"
                  transition="scale-transition"
                  offset-y
                  min-width="290px"
                >
                  <template v-slot:activator="{ on, attrs }">
                    <v-text-field
                      v-model="cancellationDate"
                      prepend-icon="mdi-calendar-remove"
                      readonly
                      outlined
                      :rules="[rules.required, rules.dateInRange]"
                      v-bind="attrs"
                      v-on="on"
                      hint="Date when leave should be cancelled (can be backdated)"
                      persistent-hint
                    >
                      <template v-slot:append>
                        <v-tooltip bottom>
                          <template v-slot:activator="{ on, attrs }">
                            <v-icon v-bind="attrs" v-on="on" color="info">
                              mdi-help-circle
                            </v-icon>
                          </template>
                          <span>
                            Select the date from which you want to cancel your
                            leave.<br />
                            Can be backdated but not before
                            {{ formatDate(requestData.startDate) }}
                          </span>
                        </v-tooltip>
                      </template>
                    </v-text-field>
                  </template>
                  <v-date-picker
                    v-model="cancellationDate"
                    :min="requestData.startDate"
                    :max="requestData.endDate"
                    @input="onCancellationDateSelected"
                  ></v-date-picker>
                </v-menu>
              </div>

              <!-- Days Calculation Display -->
              <div class="mb-4" v-if="cancellationDate">
                <v-card outlined class="pa-3 grey lighten-5">
                  <div
                    class="caption grey--text text--darken-2 mb-2 font-weight-bold"
                  >
                    Calculation Summary
                  </div>
                  <div class="d-flex justify-space-between mb-1">
                    <span class="caption">Days Utilized:</span>
                    <span class="caption font-weight-bold"
                      >{{ daysUtilized }} days</span
                    >
                  </div>
                  <div class="d-flex justify-space-between">
                    <span class="caption">Days to Cancel:</span>
                    <span class="caption font-weight-bold red--text"
                      >{{ daysToBeCancelled }} days</span
                    >
                  </div>
                </v-card>
              </div>

              <!-- Cancellation Reason -->
              <div class="mb-4">
                <div class="text-subtitle-1 font-weight-bold mb-2">
                  Reason for Cancellation *
                </div>
                <v-textarea
                  v-model="cancellationReason"
                  outlined
                  rows="4"
                  placeholder="Please provide a detailed reason for cancelling your leave..."
                  :rules="[rules.required, rules.minLength(20)]"
                  counter="500"
                  maxlength="500"
                  hint="Minimum 20 characters required"
                  persistent-hint
                ></v-textarea>
              </div>

              <!-- What Happens Next -->
              <v-timeline dense>
                <v-timeline-item color="blue" small>
                  <div class="caption">
                    Your cancellation will be sent to your supervisor, HOD, HR
                    and PS as a notification
                  </div>
                </v-timeline-item>
              </v-timeline>
            </v-form>
          </v-card-text>

          <v-divider></v-divider>

          <!-- Actions -->
          <v-card-actions class="pa-4">
            <v-btn outlined color="grey" @click="goBack">
              <v-icon left>mdi-arrow-left</v-icon>
              Back
            </v-btn>
            <v-spacer></v-spacer>
            <v-btn
              color="error"
              dark
              :disabled="!canSubmit"
              :loading="submitting"
              @click="confirmCancel"
            >
              <v-icon left>mdi-cancel</v-icon>
              Submit Cancellation
            </v-btn>
          </v-card-actions>
        </v-card>
      </v-col>
    </v-row>
  </v-container>
</template>

<script>
import processQuestionnaire from "../../mixins/processQuestionnaire";

export default {
  name: "UnpaidLeaveCancel",
  mixins: [processQuestionnaire],

  props: {
    requestId: {
      type: String,
      required: true,
    },
  },

  data() {
    return {
      url: "http://ihris.org/fhir/Questionnaire/leave-cancel",
      fhir: {},
      profile:
        "http://ihris.org/fhir/StructureDefinition/leave-request-profile",

      confirmDialog: false,
      overlay: false,
      valid: false,
      submitting: false,

      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",

      cancellationDateMenu: false,
      cancellationDate: "",
      cancellationReason: "",

      // Request data populated from leave-details-display
      requestData: {
        practitionerName: "",
        leaveCategory: "",
        startDate: "",
        endDate: "",
        days: 0,
        loadingRequest: true,
      },

      rules: {
        required: (value) => {
          if (value === undefined || value === null || value === "") {
            return "This field is required";
          }
          return true;
        },
        minLength: (min) => (value) =>
          !value || value.length >= min || `Minimum ${min} characters required`,
        dateInRange: (value) => {
          if (!value) return "Cancellation date is required";

          const cancelDate = new Date(value);
          const startDate = new Date(this.requestData.startDate);
          const endDate = new Date(this.requestData.endDate);

          if (cancelDate < startDate) {
            return `Cancellation date cannot be before leave start date (${this.formatDate(
              this.requestData.startDate,
            )})`;
          }
          if (cancelDate > endDate) {
            return `Cancellation date cannot be after leave end date (${this.formatDate(
              this.requestData.endDate,
            )})`;
          }
          return true;
        },
      },
    };
  },

  computed: {
    daysUtilized() {
      if (!this.cancellationDate || !this.requestData.startDate) return 0;

      return (
        this.$moment(this.cancellationDate).diff(
          this.requestData.startDate,
          "days",
        ) + 1
      );
    },

    daysToBeCancelled() {
      if (!this.cancellationDate || !this.requestData.endDate) return 0;

      const cancelDate = new Date(this.cancellationDate);
      const endDate = new Date(this.requestData.endDate);

      const days =
        Math.ceil((endDate - cancelDate) / (1000 * 60 * 60 * 24)) + 1;
      return Math.max(0, days);
    },

    canSubmit() {
      return (
        this.valid &&
        this.cancellationDate &&
        this.cancellationReason &&
        this.cancellationReason.length >= 20 &&
        !this.submitting &&
        !this.requestData.loadingRequest
      );
    },
  },

  methods: {
    populateRequestData(data) {
      this.requestData = { ...data, loadingRequest: false };
    },

    onCancellationDateSelected() {
      this.cancellationDateMenu = false;
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    confirmCancel() {
      this.$refs.form.validate();
      if (!this.valid) {
        this.showSnackbar("Please complete all required fields", "warning");
        return;
      }

      if (this.cancellationReason.length < 20) {
        this.showSnackbar(
          "Please provide a detailed reason (minimum 20 characters)",
          "warning",
        );
        return;
      }

      this.confirmDialog = true;
    },

    async submitCancellation() {
      if (!this.$refs.form.validate()) {
        return;
      }

      this.confirmDialog = false;
      this.submitting = true;
      this.overlay = true;

      try {
        // Build FHIR data for cancellation
        this.fhir = {
          leaveCategory: "unpaid-leave-cancel",
          requestId: this.requestId,
          cancellationDate: this.cancellationDate,
          cancellationReason: this.cancellationReason,
          daysUtilized: this.daysUtilized,
          daysToBeCancelled: this.daysToBeCancelled,
          requestDate: new Date().toISOString().split("T")[0],
        };

        // Process FHIR questionnaire
        await this.processFHIR();

        this.showSnackbar(
          "Leave cancellation request submitted successfully!",
          "success",
        );

        // Navigate back after short delay
        this.goBack();
      } catch (error) {
        console.error("Error submitting cancellation:", error);
        this.showSnackbar(
          error.message || "Error submitting cancellation request",
          "error",
        );
      } finally {
        this.overlay = false;
        this.submitting = false;
      }
    },

    showSnackbar(message, color) {
      this.snackbarMessage = message;
      this.snackbarColor = color;
      this.snackbar = true;
    },

    goBack() {
      this.$router.go(-1);
    },
  },

  components: {
    "leave-details-display": () => import("./extra-view/leave-details-display"),
  },
};
</script>

<style scoped>
.v-stepper {
  box-shadow: none !important;
}
</style>
